    u = int(data[index]) - 1
    v = int(data[index + 1]) - 1
    edges.append((u, v))
    index += 2

def is_valid_graph(n, edges):
    if n == 1:
        return True, "a"

    # Create adjacency list
    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Try to assign 'a', 'b', 'c' to each node
    def dfs(node, color, colors):
        colors[node] = color
        for neighbor in adj_list[node]:
            if colors[neighbor] == -1:
                if not dfs(neighbor, (color + 1) % 3, colors):
                    return False
            elif colors[neighbor] == color:
                return False
        return True

    colors = [-1] * n
    for i in range(n):
        if colors[i] == -1:
            if not dfs(i, 0, colors):
                return False, ""

    # Convert colors to 'a', 'b', 'c'
    result = []
    for color in colors:
        result.append("abc"[color])

    return True, "".join(result)

valid, result = is_valid_graph(n, edges)
if valid:
    print("Yes")
